      "explanation": "The study evaluates predictive accuracy across multiple treatments per patient (29 treatments in 18 patients; 10 treatments in 9 patients). The unit of analysis for the headline metric is the treatment instance."
    },
    "platform": {
      "value": "organoid",
      "evidence": [
        "article:p12",
        "article:p30"
      ],
      "explanation": "Patient-derived tumor organoids (PDTOs) grown in low-viscosity matrix suspension culture."
    },
    "readout": {
      "value": "viability",
      "evidence": [
        "article:p30",
        "article:p101"
      ],
      "explanation": "Viability quantified by mean PDTO size normalized to controls. Single agents use AUC of dose-response; combinations use mean pan-matrix viability score."
    },
    "direction": {
      "value": "lower_sensitive",
      "evidence": [
        "article:p40",
        "article:p101"
      ],
      "explanation": "Lower viability/AUC indicates higher drug sensitivity (cell death/growth inhibition). Cutoffs define 'sensitive' vs 'resistant' based on low viability thresholds relative to clinical response rates."
    },
    "threshold_rule": {
      "value": "fixed_numeric",
      "evidence": [
        "article:p40"
      ],
      "explanation": "Therapy-specific cutoff values were defined based on response rates from first-line mCRC clinical trials (e.g., 25% for 5FU, 50% for FOLFOX/FOLFIRI). These are fixed numeric thresholds applied to the viability scores."
    },
    "threshold_timing": {
      "value": "independent_reference",
      "evidence": [
        "article:p16",
        "article:p40"
      ],
      "explanation": "Cutoffs were derived from a treatment-naive community cohort (n=56) and published clinical trial response rates, then applied to an independent validation cohort of community patients receiving palliative treatment and the FORECAST-1 cohort."
    },
    "patient_mapping": {
      "value": "individual_available",
      "evidence": [
        "supp/Sheet1",
        "article:p45"
      ],
      "explanation": "Individual patient PDTO IDs are linked to clinical outcomes in the supplementary data and text."
    },
    "regimen_match": {
      "value": "matched",
      "evidence": [
        "article:p30",
        "article:p40"
      ],
      "explanation": "PDTOs were tested with standard-of-care agents (5FU, oxaliplatin, SN38, etc.) and combinations (FOLFOX, FOLFIRI) corresponding to the clinical regimens received by the patients."
    },
    "n_units": {
      "value": 39,
      "evidence": [
        "article:p56"
      ],
      "explanation": "The combined analysis of the community cohort (29 evaluable treatments) and AGITG FORECAST-1 cohort (10 evaluable treatments) totals 39 evaluable treatments."
    },
    "split": {
      "value": "independent_test",
      "evidence": [
        "article:p16",
        "article:p40",
        "article:p46"
      ],
      "explanation": "The model was developed using a treatment-naive community cohort and validated in an independent set of community patients receiving palliative care and the prospective FORECAST-1 cohort."
    }
  },
